%%\ Lab 3: Frequency-Domain Filtering with fft2
% Course: Mathematical Algorithms (DSP) — Image Processing Labs
close all; clear; clc;

if ~exist('screenshots', 'dir')
    mkdir('screenshots');
end

if exist('peppers.png', 'file')
    I0 = imread('peppers.png');
else
    I0 = repmat(imread('cameraman.tif'), 1, 1, 3);
end
I = im2double(rgb2gray(I0));
[M, N] = size(I);

%%\ 1) Magnitude spectrum (log-scale)
F = fft2(I);
Fshift = fftshift(F);
S = log(1 + abs(Fshift));

f1 = figure; %[output:6b16d503]
subplot(1, 2, 1); imshow(I, []); title('Image'); %[output:6b16d503]
subplot(1, 2, 2); imshow(S, []); title('Log-magnitude spectrum (centered)'); %[output:6b16d503]
saveas(f1, fullfile('screenshots', '01_magnitude_spectrum.png')); %[output:6b16d503]

%%\ 2) Ideal & Gaussian Low-pass in frequency
[u, v] = meshgrid( (-floor(N/2)) : (ceil(N/2)-1), (-floor(M/2)) : (ceil(M/2)-1) );
D = sqrt(u.^2 + v.^2);

D0 = 40; % cutoff radius
H_ideal_LP = double(D <= D0); % ideal circular LP

sigma = 20;
H_gauss_LP = exp(-(D.^2) / (2 * sigma^2));

f2 = figure; %[output:732e7f82]
montage({H_ideal_LP, H_gauss_LP}, 'Size', [1 2]); %[output:732e7f82]
title('Ideal LP Mask (D0 = 40) | Gaussian LP Mask (\sigma = 20)'); %[output:732e7f82]
saveas(f2, fullfile('screenshots', '02_filter_masks.png')); %[output:732e7f82]

%%\ 3) Apply LP filters in frequency domain
G_ideal = ifft2( ifftshift( H_ideal_LP .* Fshift ) );
G_gauss = ifft2( ifftshift( H_gauss_LP .* Fshift ) );

f3 = figure; %[output:10658a9b]
montage({I, real(G_ideal), real(G_gauss)}, 'Size', [1 3]); %[output:10658a9b]
title('Original | Ideal LP | Gaussian LP (ringing vs smooth)'); %[output:10658a9b]
saveas(f3, fullfile('screenshots', '03_lowpass_comparison.png')); %[output:10658a9b]

%%\ 4) High-pass via complement
H_gauss_HP = 1 - H_gauss_LP;
G_hp = real( ifft2( ifftshift( H_gauss_HP .* Fshift ) ) );
G_hp = mat2gray(G_hp);

f4 = figure; %[output:13a3867d]
montage({I, G_hp}, 'Size', [1 2]); %[output:13a3867d]
title('Original | Gaussian High-pass result'); %[output:13a3867d]
saveas(f4, fullfile('screenshots', '04_highpass_result.png')); %[output:13a3867d]

%%\ 5) Compare spatial vs frequency-domain Gaussian LP
g1d = fspecial('gaussian', [1 7], 1.2);
I_spatial_gauss = imfilter(I, g1d' * g1d, 'replicate');

f5 = figure; %[output:06e7460b]
montage({I_spatial_gauss, real(G_gauss)}, 'Size', [1 2]); %[output:06e7460b]
title('Spatial Gaussian LP | Frequency-domain Gaussian LP'); %[output:06e7460b]
saveas(f5, fullfile('screenshots', '05_spatial_vs_freq_gauss.png')); %[output:06e7460b]

